window.RP_SESSION={"id":"S-6f0234190eba","messages":[{"id":"RP-0180619","time":"2026-07-02T23:42:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"안녕하세요. 헤일리랍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180620","time":"2026-07-02T23:43:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 요새 연구에 몰두하느라 본업에 소홀했더라고요.","characters":["P-978c6ca18f92"]},{"id":"RP-0180621","time":"2026-07-02T23:46:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"뭐, 변명은 이 정도면 됐고, 작업을 시작해봅시다. 오늘 마법을 부여할 것은 가죽 신발이랍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180622","time":"2026-07-02T23:48:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"보아하니 그냥 가죽 신발이 아니라 그거군요.","characters":["P-978c6ca18f92"]},{"id":"RP-0180623","time":"2026-07-02T23:48:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그거 있잖아요. 갑옷 안에 양말처럼.","characters":["P-978c6ca18f92"]},{"id":"RP-0180624","time":"2026-07-02T23:49:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"잘 모르겠습니다. 내구성에 대한 의뢰를 받았네요. 자신의 발에 딱 맞게 길들어서 수선하거나 새로 사는건 조금 힘든 부분이 있다셨나봐요.","characters":["P-978c6ca18f92"]},{"id":"RP-0180625","time":"2026-07-02T23:52:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"일단은 마법 부여하기 좋은 상태로 만드는 게 좋겠죠. 물건이 목욕재계를 하는 겁니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180626","time":"2026-07-02T23:53:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"1단 모양이 구겨지지 않도록 안에 남는 천을 넣어줍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180627","time":"2026-07-02T23:54:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"부드러운 솔로 먼지를 털어준 뒤, 마른 천으로 전용 약품을 발라줍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180628","time":"2026-07-02T23:55:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"이때, 냄새가 독하므로 환기를 시켜두는 것에 유의!","characters":["P-978c6ca18f92"]},{"id":"RP-0180629","time":"2026-07-02T23:56:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그 다음에 작은 솔로 코팅제를 도포한 후, 큰 솔로도 해줍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180630","time":"2026-07-02T23:57:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그리고 기다립니다. 인내심은 자신 있지만요. 시간이 아까우니 짧은 독서를 합니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180631","time":"2026-07-02T23:57:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":" ...","characters":["P-978c6ca18f92"]},{"id":"RP-0180632","time":"2026-07-02T23:57:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-978c6ca18f92"]},{"id":"RP-0180633","time":"2026-07-02T23:58:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"후. 정말 아름다운 이야기였어요. 이러면 신발이 다 쉬었으니 마법 부여의 준비가 끝난거랍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180634","time":"2026-07-03T00:00:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 물건에 대한 마법 부여에는 여러 가지 방법이 있습니다. 가장 직관적인 방법은 물건에 물리적으로 주문을 세겨 넣는겁니다. 세공이라고하면 보통 이 쪽이죠.","characters":["P-978c6ca18f92"]},{"id":"RP-0180635","time":"2026-07-03T00:01:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"손끝과 눈의 감각에만 의지하다보면 끝나게 되는, 제가 좋아하는 방법이랍니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180636","time":"2026-07-03T00:02:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"하지만 가죽신발에 정을 가져다 댈 순 없는 법입니다. 그래서 저는 그 다음으로 보편적인 마법 부여를 하려해요.","characters":["P-978c6ca18f92"]},{"id":"RP-0180637","time":"2026-07-03T00:04:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그렇습니다. 그냥 물건에 주문을 때려박는겁니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180638","time":"2026-07-03T00:06:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"간단한 방법인데다가 세공에 비해 시간이 압도적으로 절약되는 방법입니다. 그러나 물건이 파괴될 가능성이 커서, 가능하면 세공의 방법이 좋습니다.","characters":["P-978c6ca18f92"]},{"id":"RP-0180639","time":"2026-07-03T00:06:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"물론 전 전문가니까! 파괴의 걱정은 안 하셔도 됩니다!","characters":["P-978c6ca18f92"]},{"id":"RP-0180640","time":"2026-07-03T00:07:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!마법","characters":["P-978c6ca18f92"]},{"id":"RP-0180641","time":"2026-07-03T00:07:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'헤일리 헤일리'의 마법 판정 :\n[2, 6, 1]\n성공수 : [ 1 ]","characters":[]},{"id":"RP-0180642","time":"2026-07-03T00:08:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"자! 보셨지요! 성공적인 마법부여 완료!","characters":["P-978c6ca18f92"]},{"id":"RP-0180643","time":"2026-07-03T00:08:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 뭐,  아직 테스트와 유예가 남았지만요.","characters":["P-978c6ca18f92"]},{"id":"RP-0180644","time":"2026-07-03T00:08:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-978c6ca18f92"]},{"id":"RP-0180645","time":"2026-07-03T00:08:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
